    low = df["low"]
    close = df["close"]

    # Inside bar: high < prev high AND low > prev low
    inside = (high < high.shift(1)) & (low > low.shift(1))

    # Three consecutive inside bars ending at bar t-1 (so bars t-3, t-2, t-1 are all inside)
