    result["fwd_3d"] = (close.shift(-3) / close * 100 - 100).loc[mask]
    result["fwd_6d"] = (close.shift(-6) / close * 100 - 100).loc[mask]
    result["fwd_12d"] = (close.shift(-12) / close * 100 - 100).loc[mask]

